import{_ as e,o as d,c as s,ag as a}from"./chunks/framework.rBpyMD18.js";const u=JSON.parse('{"title":"Models & Pricing","description":"","frontmatter":{},"headers":[],"relativePath":"models.md","filePath":"models.md","lastUpdated":1771783789000}'),o={name:"models.md"};function i(l,t,n,r,h,c){return d(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="models-pricing" tabindex="-1">Models &amp; Pricing <a class="header-anchor" href="#models-pricing" aria-label="Permalink to &quot;Models &amp; Pricing&quot;">​</a></h1><p>cloding supports any model available on <a href="https://openrouter.ai/models" target="_blank" rel="noreferrer">OpenRouter</a>. Use built-in shortcuts for popular models or pass any OpenRouter model ID directly.</p><h2 id="built-in-shortcuts" tabindex="-1">Built-in Shortcuts <a class="header-anchor" href="#built-in-shortcuts" aria-label="Permalink to &quot;Built-in Shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Model</th><th>Input $/Mtok</th><th>Output $/Mtok</th><th>vs Claude Code</th></tr></thead><tbody><tr><td><code>qwen</code></td><td>Qwen 3 Coder</td><td>$0.07</td><td>$0.30</td><td><strong>71x cheaper</strong></td></tr><tr><td><code>deepseek</code></td><td>DeepSeek Coder V3</td><td>$0.14</td><td>$0.28</td><td><strong>36x cheaper</strong></td></tr><tr><td><code>haiku</code></td><td>Claude Haiku 4.5</td><td>$0.80</td><td>$4.00</td><td>6x cheaper</td></tr><tr><td><code>gemini</code></td><td>Gemini 2.5 Pro</td><td>$1.25</td><td>$10.00</td><td>4x cheaper</td></tr><tr><td><code>sonnet</code></td><td>Claude Sonnet 4</td><td>$3.00</td><td>$15.00</td><td>1.7x cheaper</td></tr><tr><td><code>opus</code></td><td>Claude Opus 4.6</td><td>$15.00</td><td>$75.00</td><td>3x more expensive</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Default Model</p><p>The default model is <strong>Qwen 3 Coder</strong> (<code>qwen</code>). Override with <code>-m</code> or the <code>CLODING_DEFAULT_MODEL</code> environment variable.</p></div><h2 id="using-any-model" tabindex="-1">Using Any Model <a class="header-anchor" href="#using-any-model" aria-label="Permalink to &quot;Using Any Model&quot;">​</a></h2><p>Pass any OpenRouter model ID with <code>-m</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meta-llama/llama-4-scout</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> google/gemini-2.5-flash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> anthropic/claude-sonnet-4</span></span></code></pre></div><h2 id="list-all-models" tabindex="-1">List All Models <a class="header-anchor" href="#list-all-models" aria-label="Permalink to &quot;List All Models&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list-models</span></span></code></pre></div><p>This shows all configured shortcuts with their full model IDs and pricing.</p><h2 id="cost-comparison" tabindex="-1">Cost Comparison <a class="header-anchor" href="#cost-comparison" aria-label="Permalink to &quot;Cost Comparison&quot;">​</a></h2><p>A typical 30-minute coding session with Claude Code costs around <strong>$5</strong>. The same session with different models:</p><table tabindex="0"><thead><tr><th>Model</th><th>Estimated Cost</th><th>Savings</th></tr></thead><tbody><tr><td>Qwen 3 Coder</td><td>~$0.07</td><td>98.6%</td></tr><tr><td>DeepSeek Coder V3</td><td>~$0.14</td><td>97.2%</td></tr><tr><td>Claude Haiku 4.5</td><td>~$0.83</td><td>83.4%</td></tr><tr><td>Gemini 2.5 Pro</td><td>~$1.25</td><td>75.0%</td></tr><tr><td>Claude Sonnet 4</td><td>~$3.00</td><td>40.0%</td></tr></tbody></table><h2 id="custom-shortcuts" tabindex="-1">Custom Shortcuts <a class="header-anchor" href="#custom-shortcuts" aria-label="Permalink to &quot;Custom Shortcuts&quot;">​</a></h2><p>You can add your own model shortcuts by editing the <code>models.json</code> file. See <a href="/cloding/custom-models">Custom Models</a> for details.</p>`,16)])])}cons